// Uses the task's current missing facts only; the server owns both validation and rules.
export function renderVerificationForm(plan,{esc,disabled=false}={}){
 if(!plan)return '';
 const known=plan.knownFacts||[],q=plan.questions?.[0];
 return `<section class="scope-question-panel" aria-label="Xác minh thông tin"><div class="scope-known">${known.length?`<strong>Thông tin đã có</strong><ul>${known.map(f=>`<li>${esc(f.label)}: <strong>${esc(f.text)}</strong></li>`).join('')}</ul>`:''}</div>${q?`<form id="compliance-answer" class="product-form" data-fact="${esc(q.fact)}"><fieldset ${disabled?'disabled':''}><legend>${esc(q.label)}</legend>${q.specialist?'<p class="field-hint">Dùng xác nhận của kế toán hoặc người phụ trách chuyên môn. Nếu chưa có, chọn “Chưa rõ”; hệ thống không tự đoán.</p>':''}${q.help?`<p class="field-hint">${esc(q.help)}</p>`:''}${q.options?.length===2&&q.options.some(o=>o[0]==='yes')&&q.options.some(o=>o[0]==='no')?`<div class="scope-answer-actions"><button class="primary-button" name="answer" value="yes">Có</button><button class="secondary-button" name="answer" value="no">Không</button><button type="button" class="text-action" data-answer-unknown>Chưa rõ</button></div>`:`<label>Câu trả lời${q.options?`<select name="answer" required><option value="">Chọn câu trả lời</option>${q.options.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')}</select>`:`<input name="answer" type="${q.kind==='number'?'number':'date'}" ${q.kind==='number'?'min="0" max="10000000" step="1"':''} required>`}</label><div class="scope-answer-actions"><button class="primary-button">Lưu câu trả lời</button><button type="button" class="text-action" data-answer-unknown>Chưa rõ</button></div>`}<p class="field-hint">Lưu một lần, dùng cho các công việc liên quan${q.affectedCount>1?` (${q.affectedCount} việc đang chờ dữ kiện này)`:''}.</p></fieldset></form>`:''}</section>`;
}
